<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$s=new BranchService($db);if($_SERVER['REQUEST_METHOD']==='GET'){ApiGuard::permission($db,$u,'branches.view');if(isset($_GET['branch_id']))echo json_encode(['ok'=>true,'branch'=>$s->one((int)$u['business_id'],(int)$_GET['branch_id']),'local_now'=>$s->localNow((int)$u['business_id'],(int)$_GET['branch_id'])],JSON_UNESCAPED_UNICODE);elseif(isset($_GET['user_id']))echo json_encode(['ok'=>true,'branches'=>$s->assigned((int)$u['business_id'],(int)$_GET['user_id'])],JSON_UNESCAPED_UNICODE);else echo json_encode(['ok'=>true,'branches'=>$s->all((int)$u['business_id'])],JSON_UNESCAPED_UNICODE);exit;}ApiGuard::csrf();$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);$a=$d['action']??'create';if($a==='update'){ApiGuard::permission($db,$u,'branches.manage');$s->update((int)$u['business_id'],(int)$d['id'],$d);echo json_encode(['ok'=>true]);exit;}if($a==='activation'){ApiGuard::permission($db,$u,'branches.activate');$s->setActivation((int)$u['business_id'],(int)$d['id'],(string)$d['status'],(int)$u['id']);echo json_encode(['ok'=>true]);exit;}if($a==='assign'){ApiGuard::permission($db,$u,'branches.assign_users');$s->assign((int)$u['business_id'],(int)$d['user_id'],$d['branch_ids']??[],(int)($d['default_branch_id']??0));echo json_encode(['ok'=>true]);exit;}ApiGuard::permission($db,$u,'branches.manage');$id=$s->create((int)$u['business_id'],$d);echo json_encode(['ok'=>true,'branch_id'=>$id]);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}